/**
 * Country history pages (/country/{slug}): every country on earth today, with
 * the site's own article (content/articles/country/{slug}.md), who held its
 * capital on each map, the empires that covered its land, its city pages, and
 * the pages that mention it.
 *
 * countryRulers.json and countryViews.json are generated by
 * scripts/build-city-rulers.mts from the capitals in countries.json.
 */
import COUNTRIES from "@/data/countries.json";
import RULERS from "@/data/countryRulers.json";
import VIEWS from "@/data/countryViews.json";
import PLACE_MAPS from "@/data/placeMaps.json";
import { CROSSWALK, getCanonicalNameByQid, lookupBySlug } from "@/data/crosswalk";
import { CITY_LIST, withLinks, type City, type RulerSpan } from "@/lib/cityHistory";

export interface Country {
  slug: string;
  name: string;
  continent: Continent;
  wikidataId: string;
  capital: string;
  lat: number;
  lng: number;
  /** Wikidata's image for the country (a Commons file name), for link previews. */
  image?: string;
}

export type Continent = "europe" | "asia" | "africa" | "north-america" | "south-america" | "oceania";

export const CONTINENTS: { slug: Continent; label: string }[] = [
  { slug: "europe", label: "Europe" },
  { slug: "asia", label: "Asia and the Middle East" },
  { slug: "africa", label: "Africa" },
  { slug: "north-america", label: "North America and the Caribbean" },
  { slug: "south-america", label: "South America" },
  { slug: "oceania", label: "Oceania" },
];

export const COUNTRY_LIST: readonly Country[] = [...(COUNTRIES as Country[])].sort((a, b) => a.name.localeCompare(b.name));

export function getCountry(slug: string): Country | undefined {
  return COUNTRY_LIST.find((c) => c.slug === slug);
}

/** "the United States", "the Netherlands": names that read with an article. */
const WITH_THE = new Set([
  "united-states", "united-kingdom", "netherlands", "czech-republic", "central-african-republic", "philippines",
  "democratic-republic-of-the-congo", "republic-of-the-congo", "united-arab-emirates", "dominican-republic",
  "marshall-islands", "solomon-islands", "maldives", "comoros", "seychelles", "vatican-city",
]);
export const countryWithArticle = (c: Country) => (WITH_THE.has(c.slug) ? `the ${c.name}` : c.name.replace(/^The /, "the "));

/** Map view framing the modern country. */
export function countryView(slug: string): { lat: number; lng: number; zoom: number } | undefined {
  return (VIEWS as Record<string, { lat: number; lng: number; zoom: number }>)[slug];
}

/** Who held the capital on each map, oldest first, linked to atlas pages. */
export function countryRulers(slug: string): RulerSpan[] {
  // From 3000 BCE: the earlier snapshots draw Ice Age peoples tens of
  // thousands of years apart, which says little about a country's history.
  const spans = ((RULERS as Record<string, RulerSpan[]>)[slug] ?? [])
    .filter((s) => s.to === null || s.to > -3000)
    .flatMap(withLinks);
  const first = spans.findIndex((s) => s.name);
  return first === -1 ? [] : spans.slice(first);
}

/**
 * Modern-country names as they appear in the map data (placeMaps "today",
 * cities.json) → country slug. Names that match a country's own name need no entry.
 */
const NAME_TO_SLUG: Record<string, string> = {
  Burma: "myanmar",
  Byelarus: "belarus",
  Zaire: "democratic-republic-of-the-congo",
  "DR Congo": "democratic-republic-of-the-congo",
  Congo: "republic-of-the-congo",
  Swaziland: "eswatini",
  "Korea, Democratic People's Republic of": "north-korea",
  "Korea, Republic of": "south-korea",
  "Tanzania, United Republic of": "tanzania",
  "China (Tibet)": "china",
  "Israel / Palestine": "israel",
  Gambia: "gambia",
  Bahamas: "bahamas",
};

export function countrySlugFor(name: string): string | undefined {
  if (NAME_TO_SLUG[name]) return NAME_TO_SLUG[name];
  const plain = name.replace(/^the /i, "").toLowerCase();
  return COUNTRY_LIST.find((c) => c.name.replace(/^The /, "").toLowerCase() === plain)?.slug;
}

/** City pages in a country (cities.json names countries in its own way). */
export function citiesIn(country: Country): City[] {
  return CITY_LIST.filter((c) => countrySlugFor(c.country) === country.slug || (c.country === "Israel / Palestine" && country.slug === "palestine"));
}

interface PlaceMapsEntry {
  name: string;
  peak?: { year: number };
  years: number[];
  today?: { name: string; share: number }[];
}

export interface StateOverCountry {
  slug: string;
  name: string;
  /** First and last map years the state is drawn. */
  from: number;
  to: number;
  /** Share of the state's peak extent that lies in this country (0–1). */
  share: number;
}

/**
 * Empires and states with atlas pages whose land, at its height, lay partly in
 * this country, oldest first. Tiny overlaps (border slivers) are left out.
 */
export function statesOver(country: Country): StateOverCountry[] {
  const out: StateOverCountry[] = [];
  for (const [slug, data] of Object.entries(PLACE_MAPS as unknown as Record<string, PlaceMapsEntry>)) {
    const hit = data.today?.find((t) => countrySlugFor(t.name) === country.slug);
    if (!hit || hit.share < 0.02 || !data.years.length) continue;
    const entry = lookupBySlug(slug);
    const name = (entry && getCanonicalNameByQid(entry.wikidataId)) ?? data.name;
    out.push({ slug, name, from: data.years[0], to: data.years[data.years.length - 1], share: hit.share });
  }
  return out.sort((a, b) => a.from - b.from || a.name.localeCompare(b.name));
}

/** True when the atlas has a place page for this country's modern state. */
export function placePageFor(country: Country): string | undefined {
  const entry = Object.values(CROSSWALK).find((e) => e.wikidataId === country.wikidataId);
  return entry ? `/place/${entry.slug}` : undefined;
}

/**
 * Link target for a modern country named in the map data, when its history
 * page exists. `published` is the set of country slugs with an article
 * (see publishedCountries in countryPages.ts, which reads the files).
 */
export function countryHref(name: string, published: ReadonlySet<string>): string | undefined {
  const slug = countrySlugFor(name);
  return slug && published.has(slug) ? `/country/${slug}` : undefined;
}
